// Extraer conversation_id y datos del mensaje
const body = $input.item.json.body;

let conversationId = null;
let messageContent = body.content || '';
let messageType = 'text';
let audioUrl = null;

// Extraer conversation ID
if (body.conversation) {
  conversationId = body.conversation.id || 
                   body.conversation.conversation_id ||
                   (body.conversation.messages && body.conversation.messages[0] && body.conversation.messages[0].conversation_id);
}

if (!conversationId) {
  conversationId = body.conversation_id || body.id;
}

// Detectar si es mensaje de voz/audio
if (body.attachments && body.attachments.length > 0) {
  const attachment = body.attachments[0];
  if (attachment.file_type === 'audio' || attachment.file_type === 'voice') {
    messageType = 'audio';
    audioUrl = attachment.data_url;
    console.log('🎤 Mensaje de voz detectado:', audioUrl);
  }
}

console.log('🔍 DEBUG - Datos extraídos:', {
  conversationId,
  messageType,
  messageContent,
  audioUrl
});

if (!conversationId) {
  throw new Error(`❌ No se pudo encontrar conversation_id`);
}

return {
  json: {
    ...body,
    extracted_conversation_id: conversationId,
    message_type: messageType,
    message_content: messageContent,
    audio_url: audioUrl,
    source_id: body.conversation?.contact_inbox?.source_id || conversationId
  }
};

// Normalizar el mensaje (ya sea texto directo o transcripción de audio)
const inputData = $input.item.json;
let finalContent = '';

// Si viene de Whisper (audio transcrito)
if (inputData.text) {
  finalContent = inputData.text;
  console.log('✅ Audio transcrito:', finalContent);
} else {
  // Si es texto directo
  finalContent = inputData.message_content || inputData.content || '';
  console.log('✅ Texto directo:', finalContent);
}

return {
  json: {
    ...inputData,
    content: finalContent,
    normalized_message: finalContent
  }
};

// 🛡️ FASE 3: Sistema Anti-Spam con Redis
// Guarda el mensaje en cola Redis con timestamp

const Redis = require('ioredis');
const redis = new Redis({
  host: 'alvaro_redis',
  port: 6379
});

const sourceId = $input.item.json.source_id;
const messageId = $input.item.json.id || Date.now();
const timestamp = Date.now();
const content = $input.item.json.normalized_message;

const messageData = {
  id: messageId,
  timestamp: timestamp,
  content: content,
  source_id: sourceId
};

// Guardar en Redis con TTL de 10 segundos
const key = `chatwoot:queue:${sourceId}`;
await redis.setex(key, 10, JSON.stringify(messageData));

console.log('🛡️ Mensaje guardado en Redis:', {
  key,
  messageId,
  timestamp
});

redis.disconnect();

return {
  json: {
    ...$input.item.json,
    redis_key: key,
    redis_timestamp: timestamp,
    redis_message_id: messageId
  }
};

// 🛡️ FASE 3: Validar si este mensaje sigue siendo el último
// Si llegó un mensaje más nuevo, cancelar procesamiento

const Redis = require('ioredis');
const redis = new Redis({
  host: 'alvaro_redis',
  port: 6379
});

const currentMessageId = $input.item.json.redis_message_id;
const currentTimestamp = $input.item.json.redis_timestamp;
const redisKey = $input.item.json.redis_key;

// Recuperar el mensaje actual en Redis
const storedData = await redis.get(redisKey);

if (!storedData) {
  console.log('⚠️ Mensaje ya expiró en Redis, continuar de todas formas');
  redis.disconnect();
  return { json: { ...$input.item.json, should_process: true } };
}

const storedMessage = JSON.parse(storedData);

// Si el mensaje en Redis tiene un ID diferente (más nuevo), cancelar
if (storedMessage.id !== currentMessageId) {
  console.log('🛑 Mensaje cancelado: llegó uno más nuevo', {
    current: currentMessageId,
    latest: storedMessage.id
  });
  redis.disconnect();
  return { json: { ...$input.item.json, should_process: false } };
}

console.log('✅ Mensaje validado: es el último, procesar');
redis.disconnect();

return {
  json: {
    ...$input.item.json,
    should_process: true
  }
};

// Extraer la respuesta del AI Agent con validación
const respuestaCompleta = $input.item.json.output || '';
const mensajeOriginal = ($('Configuración').item.json.Mensaje || '').toString();
const categoriaAnterior = $('Configuración').item.json.Categoria_Anterior || 'interes_inicial';

let categoria = categoriaAnterior;
let confianza = 70;
let respuestaLimpia = respuestaCompleta;

const mensajeCorto = mensajeOriginal.trim().length <= 3;
const mensajesAmbiguos = ['?', '??', 'ok', 'si', 'sí', 'no', 'dale', 'bien', 'gracias'];
const esMensajeAmbiguo = mensajesAmbiguos.includes(mensajeOriginal.trim().toLowerCase());

const categoriaMatch = respuestaCompleta.match(/CATEGORÍA:\s*(interes_inicial|contacto_obtenido|seguimiento_humano|venta_cerrada|atencion_especial|pedido_reunion)/i);
if (categoriaMatch) {
  const nuevaCategoria = categoriaMatch[1].toLowerCase();

  if (mensajeCorto || esMensajeAmbiguo) {
    const categoriasOrden = {
      'interes_inicial': 1,
      'contacto_obtenido': 2,
      'seguimiento_humano': 3,
      'venta_cerrada': 4,
      'atencion_especial': 3,
      'pedido_reunion': 3
    };

    const ordenAnterior = categoriasOrden[categoriaAnterior] || 1;
    const ordenNueva = categoriasOrden[nuevaCategoria] || 1;

    if (ordenNueva > ordenAnterior || ['atencion_especial', 'pedido_reunion'].includes(nuevaCategoria)) {
      categoria = nuevaCategoria;
    } else {
      categoria = categoriaAnterior;
    }
  } else {
    categoria = nuevaCategoria;
  }

  respuestaLimpia = respuestaCompleta.replace(/CATEGORÍA:.*$/im, '').trim();
}

const confianzaMatch = respuestaCompleta.match(/CONFIANZA:\s*(\d+)/i);
if (confianzaMatch) {
  confianza = parseInt(confianzaMatch[1]);
  respuestaLimpia = respuestaLimpia.replace(/CONFIANZA:.*$/im, '').trim();
}

if (!categoriaMatch && !mensajeCorto && !esMensajeAmbiguo) {
  const mensajeLower = mensajeOriginal.toLowerCase();
  const respuestaLower = respuestaCompleta.toLowerCase();

  if (mensajeLower.includes('@') || respuestaLower.includes('alta') || respuestaLower.includes('registr')) {
    categoria = 'contacto_obtenido';
  }
  else if (respuestaLower.includes('asesor') || respuestaLower.includes('contactar') || mensajeLower.includes('comprar')) {
    categoria = 'seguimiento_humano';
  }
  else if (mensajeLower.includes('pedido') || mensajeLower.includes('orden') || respuestaLower.includes('confirmad')) {
    categoria = 'venta_cerrada';
  }
  else if (mensajeLower.includes('problema') || mensajeLower.includes('reclamo') || mensajeLower.includes('urgente')) {
    categoria = 'atencion_especial';
  }
  else if (mensajeLower.includes('reunión') || mensajeLower.includes('videollamada') || mensajeLower.includes('llamar')) {
    categoria = 'pedido_reunion';
  }
  else {
    categoria = categoriaAnterior;
  }
}

console.log('🏷️ Clasificación XIMARO:', {
  mensajeOriginal,
  mensajeCorto,
  esMensajeAmbiguo,
  categoriaAnterior,
  categoriaNueva: categoria,
  confianza
});

return {
  json: {
    respuesta: respuestaLimpia,
    categoria: categoria,
    confianza: confianza,
    conversation_id: $('Configuración').item.json.Conversation_id,
    account_id: $('Configuración').item.json.Account_id
  }
};

// 🎭 FASE 2: Sistema de Formateo Inteligente para Humanización
const respuesta = $input.item.json.respuesta || '';

function dividirEnOraciones(texto) {
  return texto.match(/[^.!?]+[.!?]+/g) || [texto];
}

function agruparEnPartes(oraciones, maxPartes = 4) {
  if (oraciones.length === 0) return [''];

  const partes = [];
  const oracionesPorParte = Math.ceil(oraciones.length / Math.min(maxPartes, oraciones.length));

  for (let i = 0; i < oraciones.length; i += oracionesPorParte) {
    const parte = oraciones.slice(i, i + oracionesPorParte).join(' ').trim();
    if (parte) partes.push(parte);
  }

  return partes;
}

if (respuesta.length < 150) {
  console.log('✅ Respuesta corta, enviar en una sola parte');
  return {
    json: {
      ...$input.item.json,
      part_1: respuesta,
      part_2: '',
      part_3: '',
      part_4: ''
    }
  };
}

const oraciones = dividirEnOraciones(respuesta);
const partes = agruparEnPartes(oraciones, 4);

console.log('🎭 Sistema de Formateo:', {
  longitudOriginal: respuesta.length,
  oraciones: oraciones.length,
  partes: partes.length
});

return {
  json: {
    ...$input.item.json,
    part_1: partes[0] || '',
    part_2: partes[1] || '',
    part_3: partes[2] || '',
    part_4: partes[3] || ''
  }
};

// 🏷️ FASE 3: Remover etiquetas anteriores antes de aplicar la nueva
const labelsActuales = $input.item.json.labels || [];
const nuevaCategoria = $('Formatear Respuesta (Multi-Parte)').item.json.categoria;

console.log('🏷️ Etiquetas a remover:', labelsActuales);
console.log('🏷️ Nueva categoría a aplicar:', nuevaCategoria);

// Categorías que deben ser removidas
const categoriasXimaro = [
  'interes_inicial',
  'contacto_obtenido',
  'seguimiento_humano',
  'venta_cerrada',
  'atencion_especial',
  'pedido_reunion'
];

// Filtrar solo las etiquetas que son categorías de XIMARO
const labelsARemover = labelsActuales.filter(label => categoriasXimaro.includes(label));

return {
  json: {
    ...$input.item.json,
    labels_a_remover: labelsARemover,
    nueva_categoria: nuevaCategoria,
    conversation_id: $('Formatear Respuesta (Multi-Parte)').item.json.conversation_id
  }
};

// Remover labels una por una usando Chatwoot API
const conversationId = $input.item.json.conversation_id;
const labelsARemover = $input.item.json.labels_a_remover || [];

for (const label of labelsARemover) {
  const url = `https://alvaro-chatwoot.5epeub.easypanel.host/api/v1/accounts/2/conversations/${conversationId}/labels`;

  await $http.request({
    method: 'POST',
    url: url,
    headers: {
      'api_access_token': 'fLi8hi4RtbiBZs4okugg9VDL',
      'Content-Type': 'application/json'
    },
    body: {
      labels: [label]
    }
  });

  console.log(`🗑️ Etiqueta removida: ${label}`);
}

return { json: $input.item.json };
